begin;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values
('a9000000-0000-0000-0000-000000000001','filing-staff@example.test'),
('a9000000-0000-0000-0000-000000000002','filing-client@example.test');
insert into vb_private.staff_members(user_id) values('a9000000-0000-0000-0000-000000000001');
insert into public.vb_clients(id,name,client_type,contact_name,portal_enabled) values('b9000000-0000-0000-0000-000000000001','Filing fixture','business','Fixture',true);
insert into public.vb_marks(id,client_id,name,mark_type,status) values('c9000000-0000-0000-0000-000000000001','b9000000-0000-0000-0000-000000000001','FIXTURE','word','not_filed');
insert into vb_private.client_memberships(client_id,user_id) values('b9000000-0000-0000-0000-000000000001','a9000000-0000-0000-0000-000000000002');
set local role anon;
select throws_ok($$select public.vb_save_filing_draft(null,null,null,0,'{}')$$,'42501',null,'Anonymous save denied');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a9000000-0000-0000-0000-000000000002","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.vb_save_filing_draft(null,null,null,0,'{}')$$,'42501',null,'Client save denied even with MFA');
select set_config('request.jwt.claims','{"sub":"a9000000-0000-0000-0000-000000000001","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select public.vb_save_filing_draft(null,null,null,0,'{}')$$,'42501',null,'Staff without MFA denied');
select set_config('request.jwt.claims','{"sub":"a9000000-0000-0000-0000-000000000001","role":"authenticated","aal":"aal2"}',true);
select lives_ok($$select public.vb_save_filing_draft('b9000000-0000-0000-0000-000000000001','c9000000-0000-0000-0000-000000000001',null,0,'{"mark":"FIRST"}')$$,'Staff draft saves');
select lives_ok($$select public.vb_save_filing_draft('b9000000-0000-0000-0000-000000000001','c9000000-0000-0000-0000-000000000001',(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),1,'{"mark":"SECOND"}')$$,'Second revision saves');
select throws_ok($$select public.vb_save_filing_draft('b9000000-0000-0000-0000-000000000001','c9000000-0000-0000-0000-000000000001',(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),1,'{}')$$,'PT409',null,'Stale save rejected');
select is((select count(*)::integer from public.vb_filing_revisions where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001')),2,'Prior revision retained');
select throws_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),1,'transfer_approval','{}')$$,'PT409',null,'Old revision approval rejected');
select throws_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),2,'readiness','{}')$$,'PT409',null,'Readiness without check rejected');
select lives_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),2,'check',jsonb_build_object('input','{"mark":"SECOND"}'::jsonb,'version','prototype-2','rows',(select jsonb_agg(jsonb_build_object('id',id,'status',case when id in ('legal','support') then 'REVIEW' else 'PASS' end)) from unnest(array['supported','contacts','owner','mark','scope','basis','legal','support']) id)))$$,'Check exact saved input');
select throws_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),2,'transfer_approval',jsonb_build_object('check_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='check' order by sequence desc limit 1)))$$,'22023',null,'Unresolved attorney reviews block transfer');
select lives_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),2,'resolution',jsonb_build_object('check_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='check' order by sequence desc limit 1),'issue_id',id,'kind','Reviewed','reason','Attorney reviewed fixture')) from unnest(array['legal','support']) id$$,'Attorney reasons recorded');
select throws_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),2,'readiness',jsonb_build_object('check_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='check' order by sequence desc limit 1),'approval_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='transfer_approval' order by sequence desc limit 1),'manual_review_confirmed',true))$$,'PT409',null,'Manual review without transfer approval rejected');
select lives_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),2,'transfer_approval',jsonb_build_object('check_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='check' order by sequence desc limit 1)))$$,'Reviewed check permits transfer approval');
select throws_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),2,'comparison',jsonb_build_object('check_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='check' order by sequence desc limit 1),'approval_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='transfer_approval' order by sequence desc limit 1),'pdf_sha256','wrong'))$$,'22023',null,'Removed comparison action rejected');
select throws_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),2,'readiness',jsonb_build_object('check_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='check' order by sequence desc limit 1),'approval_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='transfer_approval' order by sequence desc limit 1)))$$,'22023',null,'Missing manual confirmation rejected');
select throws_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),2,'readiness',jsonb_build_object('check_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='check' order by sequence desc limit 1),'approval_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='transfer_approval' order by sequence desc limit 1),'manual_review_confirmed',false))$$,'22023',null,'False manual confirmation rejected');
select throws_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),2,'readiness',jsonb_build_object('check_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='check' order by sequence desc limit 1),'approval_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='transfer_approval' order by sequence desc limit 1),'manual_review_confirmed','true'::text))$$,'22023',null,'String manual confirmation rejected');
select throws_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),2,'readiness',jsonb_build_object('check_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='check' order by sequence desc limit 1),'approval_id','00000000-0000-0000-0000-000000000000'::uuid,'manual_review_confirmed',true))$$,'PT409',null,'Wrong approval rejected');
select lives_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),2,'readiness',jsonb_build_object('check_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='check' order by sequence desc limit 1),'approval_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='transfer_approval' order by sequence desc limit 1),'manual_review_confirmed',true))$$,'Manual review records without PDF');
select is((select count(*)::integer from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='readiness'),1,'Manual review retained in history');

select lives_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),2,'check',jsonb_build_object('input','{"mark":"SECOND"}'::jsonb,'version','prototype-2','rows',(select jsonb_agg(jsonb_build_object('id',id,'status',case when id in ('legal','support') then 'REVIEW' else 'PASS' end)) from unnest(array['supported','contacts','owner','mark','scope','basis','legal','support']) id)))$$,'Rerun creates new check');
select throws_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),2,'readiness',jsonb_build_object('check_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='check' order by sequence desc limit 1),'approval_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='transfer_approval' order by sequence desc limit 1),'manual_review_confirmed',true))$$,'22023',null,'New unresolved checklist blocks manual review');
select lives_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),2,'resolution',jsonb_build_object('check_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='check' order by sequence desc limit 1),'issue_id',id,'kind','Reviewed','reason','Attorney reviewed fixture')) from unnest(array['legal','support']) id$$,'New checklist reasons recorded');
select throws_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),2,'readiness',jsonb_build_object('check_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='check' order by sequence desc limit 1),'approval_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='transfer_approval' order by sequence desc limit 1),'manual_review_confirmed',true))$$,'PT409',null,'Earlier approval cannot authorize review after new check');

select throws_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),2,'transfer_approval',jsonb_build_object('check_id',(select id from public.vb_filing_reviews where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001') and action='check' order by sequence asc limit 1)))$$,'PT409',null,'Earlier check cannot authorize new approval');
select throws_ok($$delete from public.vb_filing_revisions where draft_id=(select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001')$$,'42501',null,'History deletion denied');
select set_config('request.jwt.claims','{"sub":"a9000000-0000-0000-0000-000000000002","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.vb_record_filing_review((select id from public.vb_filing_drafts where client_id='b9000000-0000-0000-0000-000000000001'),2,'readiness','{}'::jsonb)$$,'42501',null,'Client manual review denied even with MFA');
select is((select count(*)::integer from public.vb_filing_drafts),0,'Client cannot read drafts');
select is((select count(*)::integer from public.vb_filing_revisions),0,'Client cannot read revision contents');
select is((select count(*)::integer from public.vb_filing_reviews),0,'Client cannot read internal reviews');
select * from finish(true);
rollback;
